param([Parameter(Mandatory)][string]$Executable,[Parameter(Mandatory)][string]$ProviderExecutable,[Parameter(Mandatory)][string]$DesktopFixture,[Parameter(Mandatory)][string]$ProjectRoot)
$ErrorActionPreference='Stop';$checks=0;$service=$null;$provider=$null
$root=Join-Path 'E:/Aliyat/CapabilityTests' ([Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force "$root/library","$root/application"|Out-Null
$env:TEMP="$ProjectRoot/out/build/tmp";$env:TMP=$env:TEMP;$env:HIBERNATION_SESSION_KEY='capability-session-fixture';$env:HIBERNATION_CAPABILITY_KEY='capability-model-fixture'
$headers=@{Authorization='Bearer '+$env:HIBERNATION_SESSION_KEY};$configPath="$root/config.json";$readyPath="$root/ready.json";$providerRoot="$root/provider"
function Check($Condition,$Name){if(!$Condition){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=20){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 50};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=$headers;TimeoutSec=15};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 40 -Compress))};Invoke-RestMethod @a}
function Plugin($Name,$Arguments){$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments};Wait-For {$script:last=Api '/api/plugin/result';$script:last.state-in@('succeeded','failed','paused')} $Name;return $script:last.result}
function Plan($Responses){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Responses|ForEach-Object{@{response=$_}})}|ConvertTo-Json -Depth 40|Set-Content "$providerRoot/plan.json" -Encoding utf8}
function Tool($Id,$Name,$Arguments){@{id=$Id;tool=$Name;args=$Arguments}}
function Calls($Items){@{version=1;kind='call';text=$null;calls=@($Items)}}
function Reply($Text){@{version=1;kind='reply';text=$Text;calls=@()}}
function Message($Text){$null=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text=$Text};Wait-For {!(Api '/api/chat').busy} 'message done' 35}
function Feedback{$capture=Get-Content "$providerRoot/last-request.json" -Raw|ConvertFrom-Json -Depth 60;return @(($capture.messages[-1].content|ConvertFrom-Json -Depth 50).tool_results)}
try{
 $provider=Start-Process $ProviderExecutable -ArgumentList ('"'+$providerRoot+'"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/provider.log" -RedirectStandardError "$root/provider-error.log";Wait-For {Test-Path "$providerRoot/port"} 'provider';$fixture='http://127.0.0.1:'+(Get-Content "$providerRoot/port")
 Copy-Item -LiteralPath $DesktopFixture -Destination "$root/application/Allowed.exe";Set-Content "$root/library/目录验证.txt" 'fixture text only'
 $cfg=Get-Content "$ProjectRoot/config/example.json" -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot="$root/data";$cfg.characterRoot="$ProjectRoot/character";$cfg.uiRoot="$ProjectRoot/ui";$cfg.pluginRoot="$ProjectRoot/out/build/plugins";$cfg.maxStartsPerHour=1000;$cfg.solitudeIntervalMs=600000;$cfg.idleBeforeSolitudeMs=600000
 $cfg.computer=@{enabled=$true;allowScreenCapture=$false;applications=@(@{id='fixture';name='测试程序';path="$root/application/Allowed.exe"});readRoots=@(@{id='library';path="$root/library"})}
 $cfg.plugins=@{widget=@{enabled=$true;roam=$false};television=@{enabled=$true;volume=0;wakeOnEnd=$false;platforms=@(@{id='fixture';name='本地测试平台';enabled=$true;hosts=@('127.0.0.1');homeUrl=$fixture+'/fixture/page';searchUrl=$fixture+'/fixture/page?query={query}'})}}
 $cfg.profiles+=@{id='fixture';label='Fixture';enabled=$true;protocol='chat-completions';origin=$fixture;basePath='/v1';model='fixture-model';credentialEnvironment='HIBERNATION_CAPABILITY_KEY';supportsVision=$true;timeoutMs=10000;maxOutputTokens=2048};$cfg|ConvertTo-Json -Depth 40|Set-Content $configPath -Encoding utf8
 $service=Start-Process $Executable -ArgumentList ('--desktop --config "'+$configPath+'" --ready-file "'+$readyPath+'"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/service.log" -RedirectStandardError "$root/error.log";Wait-For {if($service.HasExited){throw 'service exited'};Test-Path $readyPath} 'backend';$script:origin='http://127.0.0.1:'+((Get-Content $readyPath -Raw|ConvertFrom-Json).port);$null=Api '/api/model' @{id='fixture'}
 $inventory=Api '/api/capabilities';Check (@($inventory.tools|Where-Object tool -eq 'computer.open_application').Count-eq1-and@($inventory.tools|Where-Object tool -eq 'television.search').Count-eq1) 'model inventory contains computer and media tools';Check ($inventory.computer.applications[0].id-eq'fixture'-and!$inventory.computer.screen_capture) 'allowed application and screen scope are explicit'
 $null=Plugin 'widget.show' @{visible=$false};Check (!(Plugin 'widget.status' @{}).result.visible) 'widget can be hidden';$null=Api '/api/surfaces/show' @{id='widget'};Check (Plugin 'widget.status' @{}).result.visible 'hidden widget reopens without restart or model call'
 $settings=(Api '/api/dashboard').settings|ConvertTo-Json -Depth 40|ConvertFrom-Json -AsHashtable;$settings.plugins.widget.enabled=$false;$null=Api '/api/settings' @{settings=$settings};$null=Api '/api/surfaces/show' @{id='widget'};Check ((Api '/api/dashboard').settings.plugins.widget.enabled-and(Plugin 'widget.status' @{}).result.visible) 'explicit user show action enables a disabled installed widget'
 Plan @((Calls @((Tool 'inventory' 'capabilities.list' @{}),(Tool 'files' 'computer.list_directory' @{root='library';path=''}))),(Reply '我看到那个目录了。'));Message '看看能用的东西';$feedback=Feedback;Check ($feedback[1].ok-and$feedback[1].result.entries-contains'目录验证.txt'-and$feedback[1].source_id) 'directory listing returns real evidence within configured root'
 $capture=Get-Content "$providerRoot/last-request.json" -Raw|ConvertFrom-Json -Depth 60;Check ($capture.messages[0].content.Contains('当前能力与使用方式')-and$capture.messages[0].content.Contains('不用等待用户报出工具名')-and$capture.messages[0].content.Contains('television.search')) 'every turn teaches current affordances without the user naming them'
 Plan @((Calls @((Tool 'escape' 'computer.list_directory' @{root='library';path='../data/archive'}),(Tool 'badapp' 'computer.open_application' @{id='not-allowed'}),(Tool 'screen' 'computer.screenshot' @{target='screen'}))),(Reply '这些范围没有开放。'));Message '未授权范围验证';$feedback=Feedback;Check (@($feedback|Where-Object ok -eq $false).Count-eq3) 'directory escape unknown program and full screen capture are independently denied'
 Plan @((Calls @((Tool 'app' 'computer.open_application' @{id='fixture'}))),(Reply '它已经打开了。'));Message '打开测试程序';Wait-For {Test-Path "$root/application/launch.txt"} 'allowed application';Check ((Get-Content "$root/application/launch.txt" -Raw)-eq'clean') 'application launch succeeds without inheriting model or session secrets'
 $null=Api '/api/desktop/show' @{};Plan @((Calls @((Tool 'capture' 'computer.screenshot' @{target='application'}))),(Reply '我只能根据实际画面说。'));Message '看看本程序画面';$capture=Get-Content "$providerRoot/last-request.json" -Raw|ConvertFrom-Json -Depth 60;Check ($capture.messages[-1].content[1].image_url.url.StartsWith('data:image/jpeg;base64,')) 'application screenshot is supplied as actual multimodal input'
 $platforms=Plugin 'television.platforms' @{};Check ($platforms.result.platforms[0].id-eq'fixture') 'platform configuration is discoverable'
 $opened=Plugin 'television.search' @{query='中文测试';platform='fixture'};Check ($opened.ok-and$opened.result.mode-eq'webpage'-and$opened.result.search_page.Contains('%E4')) 'platform search opens its configured real search page'
 $page=Plugin 'television.observe' @{include_frame=$true};Check ($page.ok-and$page.result.title-eq'网页桥接验证'-and$page.result.text.Contains('实际的本地测试页面')) 'web bridge reads actual rendered page content';Check ($page.result.image.mime_type-eq'image/jpeg'-and$page.result.links[0].url.EndsWith('/fixture/video/watch')) 'web bridge observes real page pixels and playable page links';Check (!$page.result.text.Contains('never-expose-password-value')) 'page observation excludes password input values'
 $paused=Plugin 'television.control' @{action='pause'};Check $paused.ok 'web media control uses the existing page video element';$next=Plugin 'television.open_page' @{url=$page.result.links[0].url;platform='fixture'};Check $next.ok 'selected platform link opens in the same small TV';$nextPage=Plugin 'television.observe' @{include_frame=$false};Check ($nextPage.result.title-eq'选择后的影片页面') 'selected page title is observed rather than guessed'
 $denied=Plugin 'television.open_page' @{url='https://outside.invalid/'};Check (!$denied.ok-and$denied.error.code-eq'video_platform_not_configured') 'web navigation cannot escape configured platforms'
 $null=Plugin 'television.open_page' @{url=$fixture+'/fixture/page';platform='fixture'};$page=Plugin 'television.observe' @{include_frame=$false};Check ($page.result.text.Contains('页面访问次数：2')) 'platform page storage persists across navigation'
 $settings=(Api '/api/dashboard').settings|ConvertTo-Json -Depth 40|ConvertFrom-Json -AsHashtable;$settings.plugins.television.enabled=$false;$null=Api '/api/settings' @{settings=$settings};$settings.plugins.television.enabled=$true;$null=Api '/api/settings' @{settings=$settings};$null=Plugin 'television.open_page' @{url=$fixture+'/fixture/page';platform='fixture'};$page=Plugin 'television.observe' @{include_frame=$false};Check ($page.ok-and$page.result.text.Contains('页面访问次数：3')) 'platform profile survives plugin unloading and reloading'
 Copy-Item "$providerRoot/clip.mp4" "$root/data/materials/fixture.mp4";$direct=Plugin 'television.open' @{source='fixture.mp4'};Check $direct.ok 'webpage TV switches back to the engine local player';$directFrame=Plugin 'television.observe' @{include_frame=$true};Check ($directFrame.result.playback_engine-eq'AYVideoPlayer'-and$directFrame.result.image.base64.Length-gt100) 'switching back presents actual engine decoded frame'
 $null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'browser callbacks and native plugins shut down cleanly'
 @{completed=$true;checks=$checks;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content "$root/acceptance.json";Write-Output "Capabilities integration passed: $checks checks. Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
